// Dues tab: Customer, Phone, For (fees / plan / bill), Amount, Due date (yyyy-mm-dd), Status (unpaid/paid), Reminders
const today = $now.setZone('Asia/Kolkata').startOf('day');
const out = [];
for (const { json: r } of $input.all()) {
  if (!r.Phone || !r['Due date']) continue;
  const late = Math.round(today.diff(DateTime.fromISO(r['Due date'], { zone: 'Asia/Kolkata' }).startOf('day'), 'days').days);
  if (![-2, 0, 7, 15].includes(late)) continue;
  const amt = Number(r.Amount);
  const upi = `upi://pay?pa=YOUR_UPI_ID&pn=YOUR%20BUSINESS%20NAME&cu=INR&am=${amt}&tn=${encodeURIComponent(r.For + ' payment')}`;
  const rs = '₹' + amt.toLocaleString('en-IN');
  const head = late < 0 ? `Hello ${r.Customer} ji, a gentle reminder: your *${r.For}* payment of ${rs} is due in ${-late} days.`
    : late === 0 ? `Hello ${r.Customer} ji, your *${r.For}* payment of ${rs} is due today.`
    : `Hello ${r.Customer} ji, your *${r.For}* payment of ${rs} is pending for ${late} days.`;
  out.push({ json: { Phone: r.Phone, Customer: r.Customer, Reminders: Number(r.Reminders || 0) + 1, msg: `${head}\nPay by UPI: ${upi}\nAlready paid? Please ignore this message 🙏` } });
}
return out;
